import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Filter out near-duplicates based on correlation
    ids = list(feats.ids)
    x = feats.x
    y = feats.y

    # Calculate correlations
    corr_matrix = np.corrcoef(x.T)
    to_remove = set()
    for i in range(len(ids)):
        for j in range(i+1, len(ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                to_remove.add(ids[j])

    # Keep only non-duplicate features
    filtered_ids = [id for id in ids if id not in to_remove]

    if not filtered_ids:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Compute effect sizes using Welch's t-test
    effect_sizes = []
    for fid in filtered_ids:
        try:
            col_idx = feats.column(fid)
            group0 = x[y==0, col_idx]
            group1 = x[y==1, col_idx]
            if len(group0) > 0 and len(group1) > 0:
                t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
                effect_sizes.append((abs(t_stat), fid))
            else:
                effect_sizes.append((0, fid))
        except Exception:
            effect_sizes.append((0, fid))

    # Sort by effect size
    effect_sizes.sort(reverse=True)

    # Select top features
    top_features = [fid for _, fid in effect_sizes[:MAX_DRIVERS]]

    # Check for strong correlations among top features
    products = []
    if len(top_features) > 1:
        try:
            # Get indices for top features
            top_indices = []
            for fid in top_features:
                try:
                    idx = feats.column(fid)
                    top_indices.append(idx)
                except Exception:
                    continue

            if len(top_indices) >= 2:
                top_corr = np.corrcoef(x[:, top_indices].T)

                # Create products between correlated features
                for i in range(len(top_features)):
                    for j in range(i+1, len(top_features)):
                        if abs(top_corr[i,j]) >= 0.6:
                            products.append((top_features[i], top_features[j]))
        except Exception:
            pass

    # Return design
    return Design(
        drivers=tuple(top_features),
        columns=tuple(filtered_ids),
        products=tuple(products),
        loadings={fid: 1.0 for fid in filtered_ids}
    )
